package com.simon.voiceime;
import android.graphics.*;import android.view.*;import android.widget.*;import android.os.*;import org.json.*;import java.util.*;
/** FIX6 requirements: 18sp symbol ink fits, approved AI green, 4px tab elevation in every state. */
public class App690Fix6Test extends App690FSupport {
 private final JSONArray rows=new JSONArray();
 private void theme(String name)throws Exception {inst.getTargetContext().getSharedPreferences("simon_ime_prefs",0).edit().putString("keyboard_theme",name).commit();main(()->{call(service,"onStartInputView",call(service,"getCurrentInputEditorInfo"),true);return null;});page("dual_hand");}
 private List<TextView> symbols(View v){List<TextView> a=new ArrayList<>();if(v instanceof TextView&&"symbol".equals(v.getTag(inst.getTargetContext().getResources().getIdentifier("keyboard_content_kind","id",inst.getTargetContext().getPackageName()))))a.add((TextView)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)a.addAll(symbols(((ViewGroup)v).getChildAt(i)));return a;}
 private JSONObject ink(TextView t,String theme,String stage)throws Exception {
  Rect b=new Rect();String s=t.getText().toString();t.getPaint().getTextBounds(s,0,s.length(),b);android.text.Layout l=t.getLayout();Rect visible=rect(t);visible.inset(Math.round(density()),Math.round(density()));Rect clip=new Rect();t.getGlobalVisibleRect(clip);int[] sr=new int[2],wr=new int[2];t.getRootView().getLocationOnScreen(sr);t.getRootView().getLocationInWindow(wr);clip.offset(sr[0]-wr[0],sr[1]-wr[1]);visible.intersect(clip);Rect at=rect(t);float x=at.left+t.getCompoundPaddingLeft()-t.getScrollX()+l.getLineLeft(0),y=at.top+t.getBaseline()-t.getScrollY();float[] bounds={x+b.left,y+b.top,x+b.right,y+b.bottom};Paint.FontMetricsInt fm=t.getPaint().getFontMetricsInt();float[] margins={bounds[0]-visible.left,bounds[1]-visible.top,visible.right-bounds[2],visible.bottom-bounds[3]};boolean fits=true;for(float m:margins)fits&=m>=0;
  return new JSONObject().put("text",s).put("theme",theme).put("stage",stage).put("ink_bounds",new JSONArray(bounds)).put("visible",new JSONArray(new int[]{visible.left,visible.top,visible.right,visible.bottom})).put("margins",new JSONArray(margins)).put("fits",fits).put("baseline",t.getBaseline()).put("scrollY",t.getScrollY()).put("font_padding",t.getIncludeFontPadding()).put("layout_height",l.getHeight()).put("line_baseline",l.getLineBaseline(0)).put("font_metrics",new JSONArray(new int[]{fm.top,fm.ascent,fm.descent,fm.bottom})).put("view_size",new JSONArray(new int[]{t.getWidth(),t.getHeight()})).put("padding",new JSONArray(new int[]{t.getPaddingLeft(),t.getPaddingTop(),t.getPaddingRight(),t.getPaddingBottom()})).put("text_sp",sizeSp(t)).put("bundled",call(api("KeyboardTypeface"),"bundled",t.getTypeface()));
 }
 public void testSymbolInk()throws Exception {
  try{for(String th:new String[]{"dark","light"}){theme(th);main(()->{call(service,"dualHandPanel","symbols");return null;});inst.waitForIdleSync();Thread.sleep(200);List<TextView> cells=main(()->symbols((View)field(service,"panelContainer")));assertEquals("all 25 fixed symbols",25,cells.size());for(TextView t:cells)rows.put(main(()->ink(t,th,"product")));
   if(androidx.test.platform.app.InstrumentationRegistry.getArguments().getString("diagnose","false").equals("true")){main(()->{for(TextView t:cells)t.setIncludeFontPadding(false);return null;});inst.waitForIdleSync();Thread.sleep(100);for(TextView t:cells)rows.put(main(()->ink(t,th,"no-font-padding")));}
  }}finally{save("fix6.json",rows);}for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.getString("stage").equals("product")){assertEquals(18.,r.getDouble("text_sp"),.001);assertTrue(r.getBoolean("bundled"));assertTrue(r.toString(),r.getBoolean("fits"));JSONArray b=r.getJSONArray("ink_bounds"),v=r.getJSONArray("visible");assertEquals("actual ink center "+r,(v.getDouble(1)+v.getDouble(3))/2,(b.getDouble(1)+b.getDouble(3))/2,.5);}}
 }
 public void testAiColor()throws Exception {
  theme("light");main(()->{Object b=call(dual(),"buffer");call(b,"clearBuffer");for(int i=0;i<9;i++)for(String key:new String[]{"1","A"}){long time=1000L+i*400+(key.equals("A")?100:0);Object stroke=call(b,"begin",key,time);call(b,"end",stroke,"tap",false);call(b,"drain",time+100);}call(dual(),"refresh");return null;});
  try{for(String state:new String[]{"over8","ai_shown"}){if(state.equals("ai_shown"))main(()->{call(call(dual(),"buffer"),"applyAi","一".repeat(9));call(dual(),"refresh");return null;});rows.put(main(()->{TextView t=(TextView)((Map<?,?>)((Map<?,?>)field(dual(),"labels")).get("core")).get("down");return new JSONObject().put("state",state).put("text",t.getText()).put("color",t.getCurrentTextColor()).put("role",t.getTag(inst.getTargetContext().getResources().getIdentifier("keyboard_text_role","id",inst.getTargetContext().getPackageName())));}));}}finally{save("fix6.json",rows);}for(int i=0;i<rows.length();i++)assertEquals(rows.getJSONObject(i).toString(),0xff077256,rows.getJSONObject(i).getInt("color"));
 }
 private JSONObject tab(Button b,String th,String stage)throws Exception {return new JSONObject().put("text",b.getText()).put("theme",th).put("stage",stage).put("elevation_px",b.getElevation()).put("translationZ",b.getTranslationZ()).put("scale",b.getScaleX()).put("pressed",b.isPressed()).put("animator",b.getStateListAnimator()==null?"null":b.getStateListAnimator().getClass().getName());}
 public void testTabElevation()throws Exception {
  try{for(String th:new String[]{"dark","light"}){theme(th);main(()->{Object p=null;for(Object x:api("SimonIMEService$Panel").getEnumConstants())if(x.toString().equals("COMMANDS"))p=x;call(service,"showPanel",p);return null;});inst.waitForIdleSync();Thread.sleep(250);ViewGroup tabs=main(()->((View)field(service,"panelContainer")).findViewById(inst.getTargetContext().getResources().getIdentifier("cmdGroupTabs","id",inst.getTargetContext().getPackageName())));assertTrue(tabs.getChildCount()>=5);
   for(int i=0;i<tabs.getChildCount();i++){final int at=i;Button b=main(()->(Button)tabs.getChildAt(at));Rect visible=new Rect();if(!main(()->b.getGlobalVisibleRect(visible)))continue;
    for(String state:new String[]{"idle","pressed","released","selected","activated","disabled","restored"}){main(()->{if(state.equals("pressed")){MotionEvent e=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),MotionEvent.ACTION_DOWN,b.getWidth()/2f,b.getHeight()/2f,0);b.dispatchTouchEvent(e);e.recycle();}if(state.equals("released")){MotionEvent e=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),MotionEvent.ACTION_CANCEL,0,0,0);b.dispatchTouchEvent(e);e.recycle();}if(state.equals("selected"))b.setSelected(true);if(state.equals("activated"))b.setActivated(true);if(state.equals("disabled"))b.setEnabled(false);if(state.equals("restored")){b.setEnabled(true);b.setSelected(false);b.setActivated(false);}return null;});Thread.sleep(state.equals("pressed")?100:300);rows.put(main(()->tab(b,th,state)));}
    if(androidx.test.platform.app.InstrumentationRegistry.getArguments().getString("diagnose","false").equals("true")){main(()->{b.setStateListAnimator(null);b.setElevation(4);b.setTranslationZ(0);b.setPressed(true);return null;});Thread.sleep(200);rows.put(main(()->tab(b,th,"animator-removed")));}
   }
  }}finally{save("fix6.json",rows);}for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);assertEquals(r.toString(),(float)Math.round(1.5f*density()),(float)r.getDouble("elevation_px"),.01f);assertEquals(r.toString(),0f,(float)r.getDouble("translationZ"),.01f);if(r.getString("stage").equals("pressed"))assertEquals(.96f,(float)r.getDouble("scale"),.01f);if(r.getString("stage").equals("released"))assertEquals(1f,(float)r.getDouble("scale"),.01f);}
 }
}
